(7624328, 1235167, 59740, '<td valign="top">Great photo but I don''t see it relating to perspective compression</td>', 'Great photo but I don''t see it relating to perspective compression', '2019-04-12 14:55:08.000000', NULL, 1),
(7624329, 1235500, 59740, '<td valign="top">Nice shot but IMO it is the opposite of compression. Because of the extreme closeness to the subject the front of the bike seems farther from the rear than it actually is.</td>', 'Nice shot but IMO it is the opposite of compression. Because of the extreme closeness to the subject the front of the bike seems farther from the rear than it actually is.', '2019-04-12 14:57:52.000000', NULL, 1),
(7624393, 1235317, 153275, '<td valign="top">looks like the boats are stick to the buildings, while I guess there is a street or quay in between, so a very good take on perspective compression. I also like the colors of the buildings and the reflection in the water. Top 3</td>', 'looks like the boats are stick to the buildings, while I guess there is a street or quay in between, so a very good take on perspective compression. I also like the colors of the buildings and the reflection in the water. Top 3', '2019-04-13 04:36:23.000000', NULL, 1),
